from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    fill = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg or (r, c) in seen:
                continue
            seen.add((r, c))
            component = {(r, c)}
            stack = [(r, c)]
            while stack:
                x, y = stack.pop()
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if (0 <= nx < h and 0 <= ny < w and grid[nx][ny] == bg
                            and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        component.add((nx, ny))
                        stack.append((nx, ny))
            r0 = min(x for x, _ in component)
            r1 = max(x for x, _ in component)
            c0 = min(y for _, y in component)
            c1 = max(y for _, y in component)
            if len(component) != (r1 - r0 + 1) * (c1 - c0 + 1):
                continue
            boundary = [
                (x, y) for x, y in component
                if x in (0, h - 1) or y in (0, w - 1)
            ]
            sides = set()
            if any(x == 0 for x, _ in boundary):
                sides.add("top")
            if any(x == h - 1 for x, _ in boundary):
                sides.add("bottom")
            if any(y == 0 for _, y in boundary):
                sides.add("left")
            if any(y == w - 1 for _, y in boundary):
                sides.add("right")
            if not boundary or (len(sides) == 1 and len(boundary) == 2):
                fill.update(component)
    out = [row[:] for row in grid]
    for r, c in fill:
        out[r][c] = 4
    return out
